H('312.d.4.B',4,"Constructive play means children:","build or create something with materials",["only watch others","avoid objects","only run"],"Constructive play makes things.")
H('312.d.5.A',3,"Guidance that teaches children self-control through clear expectations is:","positive guidance",["physical punishment","humiliation","neglect"],"Positive guidance teaches skills.")
H('312.d.5.A',4,"Natural consequences differ from logical consequences because natural consequences:","happen without adult intervention",["are chosen by the teacher","are always punishments","are unrelated to behavior"],"Natural results occur on their own.")
H('312.d.5.B',3,"A child refuses to clean up blocks. A caregiver should first:","calmly remind the child of the rule and offer help",["yell","take away lunch","laugh at the child"],"Calm reminders guide behavior.")
H('312.d.5.B',4,"Giving a child two acceptable choices is a guidance technique that:","allows some control while setting limits",["removes all rules","teaches fear","avoids responsibility"],"Choices give autonomy within limits.")
H('312.d.5.C',3,"Which is NOT an appropriate guidance technique?","Hitting a child",["Redirection","Giving choices","Using a calm voice"],"Physical punishment is never appropriate in child care.")
H('312.d.5.C',4,"Behavior that could be considered child abuse includes:","hitting, shaming, or withholding food as punishment",["setting nap times","giving time-in","offering choices"],"These acts harm children.")
H('312.d.6.A',3,"A sensory table filled with sand or water develops:","sensory skills",["tax skills","career skills","driving skills"],"Sensory play explores touch.")
H('312.d.6.A',4,"Smelling herbs and feeling different fabrics are activities that stimulate children's:","senses of smell and touch",["reading speed","math fluency","spelling"],"These engage the senses.")
H('312.d.6.B',3,"Reading aloud and singing songs develops children's:","language skills",["driving skills","tax skills","knot-tying only"],"Words and rhythm build language.")
H('312.d.6.B',4,"A caregiver who describes what a toddler is doing ('You are stacking the red block') is:","building vocabulary through narration",["limiting language","teaching math","punishing the child"],"Narration adds words to experience.")
H('312.d.6.C',3,"Stringing large beads helps develop:","fine motor skills",["gross motor skills","hearing","taste"],"Hand and finger control is fine motor.")
H('312.d.6.C',4,"Playing hopscotch develops:","balance and gross motor skills",["fine motor skills only","reading skills","memorization"],"Hopping builds balance and large-muscle control.")
H('312.d.6.D',3,"Group games such as 'Duck, Duck, Goose' help children develop:","social skills",["tax skills","solitary behavior","legal skills"],"Games teach turn-taking and interaction.")
H('312.d.6.D',4,"Helping children name and talk about feelings supports their:","social-emotional development",["physical strength","visual tracking","tooth growth"],"Naming feelings builds emotional skills.")
H('312.d.7.A',3,"A lesson plan for physical skills in preschool could include:","an obstacle course with crawling and balancing",["a long worksheet","a quiet video","a spelling test"],"Movement builds physical skills.")
H('312.d.7.A',4,"A lesson plan objective for catching a ball should state:","what the child will be able to do",["the teacher's schedule","the room color","the snack menu"],"Objectives name the learner's outcome.")
H('312.d.7.B',3,"A lesson on animal names could build vocabulary by using:","picture cards and animal sounds",["tax forms","silent seat work","adult magazines"],"Concrete cues help children learn words.")
H('312.d.7.B',4,"Which activity builds preschool vocabulary?","Reading a story and discussing new words",["Silent sorting only","Memorizing laws","Copying long paragraphs"],"Talking about new words builds language.")
H('312.d.7.C',3,"Counting blocks and sorting them by color builds early:","math skills",["driving skills","reading speed","tax knowledge"],"Counting and sorting are early math.")
H('312.d.7.C',4,"Comparing 'bigger' and 'smaller' objects develops:","measurement concepts",["spelling skills","geography","history"],"Comparison leads to measurement.")
H('312.d.7.D',3,"Planting seeds and watching them grow teaches preschoolers about:","living things and change",["tax law","computer programming","world wars"],"Plant growth shows life cycles.")
H('312.d.7.D',4,"A simple science activity for preschoolers is:","observing what sinks or floats in water",["dissecting animals","mixing dangerous chemicals","using a microscope alone"],"Safe exploration builds science thinking.")
H('312.d.7.E',3,"A lesson plan to teach feelings might use:","feeling faces cards and a story",["a tax table","a map of Europe","a math quiz"],"Visuals help children name emotions.")
H('312.d.7.E',4,"Role-playing how to ask a friend to share a toy teaches:","social problem solving",["spelling","measurement","gross motor skills"],"Practicing words helps children resolve conflicts.")
H('312.d.8.A',3,"A school-age physical skills lesson could include:","relay races and jump rope",["silent reading","taking a test","board games only"],"Active games build fitness.")
H('312.d.8.A',4,"A lesson on teamwork in sports for school-age children should also teach:","fair play and safety rules",["only winning","how to avoid teammates","cheating"],"Sportsmanship is part of the lesson.")
H('312.d.8.B',3,"A lesson for early elementary reading might include:","phonics games and read-alouds",["tax tables","driving lessons","stock charts"],"Phonics builds decoding.")
H('312.d.8.B',4,"A guided reading group helps school-age children:","practice reading at their own level with teacher support",["avoid books","memorize unrelated facts","skip comprehension"],"Groups match text to ability.")
H('312.d.8.C',3,"A school-age math lesson on addition might use:","counters or manipulatives",["a stock report","a driving test","a poem"],"Hands-on objects make addition concrete.")
H('312.d.8.C',4,"Measuring ingredients in a classroom cooking activity teaches:","fractions and measurement",["only vocabulary","only handwriting","only sports"],"Cooking applies math.")
H('312.d.8.D',3,"A hands-on science lesson for school-age children could be:","growing a plant and recording its height",["memorizing a list of laws","filling out tax forms","playing a video game"],"Observation and recording are science skills.")
H('312.d.8.D',4,"The scientific method begins with:","asking a question",["publishing results","writing a conclusion","buying supplies"],"Inquiry starts with a question.")
H('312.d.8.E',3,"A lesson about conflict resolution teaches children to:","solve disagreements with words",["avoid all friends","ignore feelings","argue louder"],"Words resolve conflicts.")
H('312.d.8.E',4,"An 'I-message' such as 'I feel upset when...' helps children:","express feelings without blaming",["blame others","avoid talking","shout"],"I-messages focus on feelings.")
H('312.d.9.A',3,"Choosing a career that requires frequent travel can affect:","family time and personal goals",["only the weather","only the price of gas","nothing at all"],"Careers shape home life.")
H('312.d.9.A',4,"A child care worker's schedule might affect family goals by:","requiring early morning start times",["guaranteeing weekends off","removing the need for planning","providing unlimited vacation"],"Work hours affect family routines.")
H('312.d.9.B',3,"Patience, creativity, and communication are aptitudes useful for:","working with young children",["operating heavy machinery alone","trading stocks","long-haul trucking"],"These traits support early childhood work.")
H('312.d.9.B',4,"A student who enjoys helping children learn might assess their interests by:","completing a career interest inventory",["flipping a coin","skipping class","guessing"],"Inventories identify fit.")
H('312.d.9.C',3,"A short-term career goal could be to:","earn a CPR certification this semester",["become a center director in 20 years","retire at age 65","own a school district"],"Short-term goals are reachable soon.")
H('312.d.9.C',4,"A long-term career goal in early childhood could be to:","open a licensed child care center",["finish tonight's reading","buy lunch Friday","attend a pep rally"],"Long-term goals take years.")
H('312.d.9.D',3,"An entrepreneurial opportunity in early childhood is:","starting a family child care home",["working for a government agency","joining the military","being a student only"],"Owners run their own programs.")
H('312.d.9.D',4,"Employment opportunities for early childhood graduates include:","preschool teacher or child care center staff",["airline pilot","petroleum engineer","court judge"],"These jobs match the training.")
H('312.d.9.E',3,"A common requirement for lead teachers in many child care centers is:","a CDA credential or college coursework",["no training","a pilot license","a law degree"],"Credentials show preparation.")
H('312.d.9.E',4,"A bachelor's degree in early childhood education can lead to:","teaching public school pre-K",["practicing medicine","flying planes","practicing law"],"The degree supports teacher certification.")

# ---- 313 Child Guidance / Early Childhood Education ----
H('313.d.1.A',3,"A safe indoor classroom has:","clear exits and covered outlets",["blocked doors","exposed cords","unlabeled chemicals"],"Safety means clear paths and protected hazards.")
H('313.d.1.A',4,"Furniture in a preschool room should be:","child-sized, sturdy, and arranged for visibility",["tall and wobbly","stacked high","blocking the view"],"Teachers must see all children.")
H('313.d.1.B',3,"A safe outdoor play area has:","soft surfacing under climbers",["concrete under climbers","broken equipment","open gates to the street"],"Soft surfaces reduce fall injuries.")
H('313.d.1.B',4,"Before outdoor play, teachers should:","inspect the playground for hazards",["skip supervision","ignore weather","leave the gate open"],"Daily checks prevent injuries.")
H('313.d.1.C',3,"A difference between center-based and home-based programs is that centers usually have:","more children and more staff",["no rules","no schedules","no learning"],"Centers are larger.")
H('313.d.1.C',4,"Head Start programs primarily serve:","children from low-income families",["only college students","only teenagers","only adults"],"Head Start supports early learning for families with low incomes.")
H('313.d.1.D',3,"Handwashing in a classroom helps to:","prevent the spread of germs",["increase illness","dry the skin","save water"],"Handwashing is the best defense against germs.")
H('313.d.1.D',4,"A child who has a fever should:","be separated and picked up by a parent",["stay in group play","share toys","eat with friends"],"Sick children should go home.")
H('313.d.1.E',3,"Learning centers such as blocks, art, and a book nook help children:","choose engaging activities",["sit silently","avoid choices","stay in one place all day"],"Centers invite exploration.")
H('313.d.1.E',4,"A classroom that encourages engagement displays children's:","own artwork at their eye level",["adult tax forms","only commercial posters","nothing at all"],"Displaying their work shows value.")
H('313.d.2.A',3,"Which activity promotes gross motor development?","Throwing and catching",["Threading beads","Drawing with crayons","Cutting paper"],"Big movements use large muscles.")
H('313.d.2.A',4,"Squeezing playdough and using tweezers promote:","fine motor development",["gross motor development","hearing","taste"],"Small hand movements build fine motor skill.")
H('313.d.2.B',3,"Puzzles and sorting games promote:","cognitive development",["tax knowledge","legal knowledge","financial planning"],"These build thinking skills.")
H('313.d.2.B',4,"Asking open-ended questions like 'What do you think will happen?' encourages:","critical thinking",["silence","memorization only","fear of mistakes"],"Open questions prompt reasoning.")
H('313.d.2.C',3,"Shared book reading builds:","language and early literacy",["tax skills","driving skills","silent behavior"],"Reading together grows language.")
H('313.d.2.C',4,"A print-rich environment includes:","labels, signs, and books at children's level",["no text","only adult magazines","blank walls"],"Print everywhere builds literacy.")
H('313.d.2.D',3,"Painting, music, and dramatic play give children a chance for:","creative expression",["rote copying","silence","test taking"],"The arts let children express ideas.")
H('313.d.2.D',4,"Open-ended art, such as free painting, is valuable because it:","lets children express ideas in their own way",["requires copying a model","limits creativity","produces identical results"],"No single right answer.")
H('313.d.3.A',3,"A warm, positive relationship between teacher and child builds:","trust and security",["fear","distance","distrust"],"Secure relationships support learning.")
H('313.d.3.A',4,"Greeting each child by name at arrival helps children feel:","welcomed and valued",["ignored","unimportant","afraid"],"Personal greetings build belonging.")
H('313.d.3.B',3,"Displaying books and pictures that reflect all children's families helps children:","feel proud of their heritage",["feel excluded","hide their identity","avoid differences"],"Seeing yourself reflected builds pride.")
H('313.d.3.B',4,"Inviting families to share traditions teaches children to:","respect and appreciate cultural differences",["fear differences","ignore others","compete"],"Sharing builds understanding.")
H('313.d.3.C',3,"Teaching children to take turns and cooperate helps them function effectively in:","a group",["isolation only","a courtroom","a laboratory"],"Group skills are learned early.")
H('313.d.3.C',4,"A morning meeting where each child has a role helps children learn to:","work together as part of a community",["work alone only","avoid rules","skip participation"],"Roles build community.")
H('313.d.3.D',3,"Adverse childhood experiences (ACEs) are:","stressful or traumatic events that happen in childhood",["school field trips","vaccines","birthday parties"],"ACEs can affect long-term health.")
H('313.d.3.D',4,"A teacher can buffer the effects of ACEs by being:","a consistent, caring adult",["unpredictable","punitive","absent"],"Stable relationships protect children.")
H('313.d.4.A',3,"A classroom management plan helps by:","setting clear expectations and routines",["creating confusion","removing rules","increasing conflict"],"Plans make the day predictable.")
H('313.d.4.A',4,"Which is part of a classroom management plan?","Rules, routines, and consequences",["Tax forms","Teacher salary","Building permits"],"A plan defines how the classroom runs.")
H('313.d.4.B',3,"A child bites when frustrated. A teacher should respond by:","staying calm and teaching words to express feelings",["biting back","shaming the child","ignoring danger"],"Teach alternatives to the behavior.")
H('313.d.4.B',4,"Challenging behavior is often a way children:","communicate unmet needs",["plan to annoy adults","show no feelings","avoid friends on purpose"],"Behavior is communication.")
H('313.d.4.C',3,"Which is a positive guidance technique?","Redirection",["Time-out for hours","Yelling","Threats"],"Redirection guides without harm.")
H('313.d.4.C',4,"Catching a child being good and naming the behavior is called:","positive reinforcement",["punishment","ignoring","bribery"],"Specific praise strengthens good behavior.")
H('313.d.5.A',3,"A tool in which a teacher writes short notes about what a child says and does is an:","anecdotal record",["attendance chart","lunch menu","fire drill log"],"Anecdotal records capture moments.")
H('313.d.5.A',4,"A checklist used to record whether a child has mastered a skill is an example of:","an assessment tool",["a punishment","a lesson plan","a floor plan"],"Checklists track progress.")
H('313.d.5.B',3,"Observation helps a teacher plan by showing:","what a child is ready to learn next",["what the child ate","what the child wears","what the family earns"],"Observation guides instruction.")
H('313.d.5.B',4,"After noticing that several children love dinosaurs, a teacher plans a dinosaur unit. This is:","using observations to plan curriculum",["ignoring interests","punishing students","copying another class"],"Curriculum follows children's interests.")
H('313.d.5.C',3,"An objective observation records:","only what a teacher sees and hears",["the teacher's opinions","guesses about feelings","rumors from others"],"Objective notes are facts.")
H('313.d.5.C',4,"Which is an objective statement?","The child stacked six blocks.",["The child is gifted.","The child is naughty.","The child is lazy."],"Facts, not labels.")
H('313.d.6.A',3,"A family with two parents and their children is a:","nuclear family",["extended family","blended family","single-parent family"],"A nuclear family is parents and children.")
H('313.d.6.A',4,"A family in which grandparents, aunts, or uncles live with the parents and children is an:","extended family",["nuclear family","blended family","single-parent family"],"Extended families include other relatives.")
H('313.d.6.B',3,"A teacher can build a partnership with families by:","inviting families to participate and share ideas",["avoiding contact","sharing only bad news","limiting visits"],"Partnerships are two-way.")
H('313.d.6.B',4,"A family-teacher conference should focus on:","the child's progress and goals",["the teacher's problems","other families' private information","unrelated gossip"],"Conferences center on the child.")
H('313.d.6.C',3,"Which method helps teachers reach families who speak another language?","Translated notes or an interpreter",["English-only notes","no communication","phone calls at midnight"],"Language access builds partnership.")
H('313.d.6.C',4,"Daily communication tools such as apps and newsletters help families:","stay informed about classroom activities",["avoid the school","skip conferences","lose track of events"],"Regular updates keep families connected.")
H('313.d.7.A',3,"Professionalism with coworkers includes:","respectful communication and teamwork",["gossiping","ignoring requests","blaming others"],"Professional teams cooperate.")
H('313.d.7.A',4,"A teacher who arrives on time, dresses appropriately, and keeps confidences shows:","professionalism",["carelessness","bias","favoritism"],"These habits show professional behavior.")
H('313.d.7.B',3,"To resolve a disagreement with a coworker, a teacher should:","listen and look for a solution together",["complain to parents","ignore it forever","argue in front of children"],"Problem solving is respectful.")
H('313.d.7.B',4,"Using 'I' statements in a conflict helps because they:","express feelings without blaming",["blame the other person","escalate anger","avoid the issue entirely"],"I-statements reduce defensiveness.")
H('313.d.7.C',3,"Teaching with intentionality means:","planning activities with a clear purpose",["acting without thinking","copying others","filling time"],"Intentional teachers know why they teach.")
H('313.d.7.C',4,"A teacher who can explain why each activity supports a learning goal is:","teaching with intentionality",["improvising randomly","skipping planning","filling space"],"Purposeful choices define intentional teaching.")
H('313.d.7.D',3,"Advocating for early childhood education can include:","sharing research on its benefits with community leaders",["closing programs","hiding data","cutting funding"],"Advocates make the case.")
H('313.d.7.D',4,"Research shows high-quality early education can lead to:","better outcomes in school and later life",["lower graduation rates","more school absences","no effects at all"],"Early learning has lasting benefits.")
H('313.d.8.A',3,"A professional portfolio might include:","a resume, lesson plans, and references",["a grocery list","a game score","unrelated photos"],"Portfolios show qualifications.")
H('313.d.8.A',4,"A work sample in an early childhood portfolio could be:","a lesson plan you wrote",["a friend's lesson plan","a recipe card","a receipt"],"Samples must be your own work.")
H('313.d.8.B',3,"When presenting a portfolio to a director, a student should:","explain each item and what it shows about their skills",["read silently","skip items","argue with questions"],"Explanations connect work to skills.")
H('313.d.8.B',4,"At the end of a portfolio presentation, a good next step is to:","ask for feedback and thank the reviewers",["leave abruptly","argue with comments","ignore feedback"],"Feedback supports growth.")

# ---- 314 Instructional Practices / Technology for educators ----
H('314.d.1.A',3,"A teacher's emails to parents should be:","professional, respectful, and clear",["casual and full of slang","emotional","careless"],"Professional communication builds trust.")
H('314.d.1.A',4,"Educator codes of ethics require teachers to communicate with students:","professionally and appropriately",["as personal friends","through private chats at midnight","only socially"],"Boundaries protect students.")
H('314.d.1.B',3,"A teacher should contact parents promptly when a student has:","a serious injury or safety concern",["a new haircut","a lost pencil","a favorite color"],"Safety issues require quick contact.")
H('314.d.1.B',4,"Which situation requires a school to notify the community?","An emergency such as a lockdown or weather closure",["a new bulletin board","a pencil sale","a lost sock"],"Emergencies require timely notice.")
H('314.d.1.C',3,"An appropriate use of social media by a teacher is:","sharing classroom learning tips on an approved school account",["friending students privately","posting student grades","venting about students"],"Professional accounts serve learning.")
H('314.d.1.C',4,"A teacher posting a photo of students online should first:","confirm that the district and parents allow it",["post immediately","tag the students","share personal addresses"],"Permission is required.")
H('314.d.1.D',3,"A teacher who has an inappropriate relationship with a student can face:","loss of their teaching certificate and criminal charges",["a raise","a promotion","an award"],"Misconduct has severe consequences.")
H('314.d.1.D',4,"Educator misconduct in Texas is investigated through the:","State Board for Educator Certification",["school cafeteria","local newspaper","student council"],"SBEC oversees educator certification.")
H('314.d.2.A',3,"Effective verbal communication with parents includes:","speaking clearly and respectfully",["interrupting","using jargon","speaking harshly"],"Clear, respectful speech builds partnership.")
H('314.d.2.A',4,"When explaining test results to a parent, a teacher should avoid:","unexplained technical jargon",["clear examples","plain language","a calm tone"],"Plain language helps families understand.")
H('314.d.2.B',3,"Active listening includes:","paraphrasing and asking clarifying questions",["interrupting","looking away","planning a reply while the speaker talks"],"Active listeners confirm understanding.")
H('314.d.2.B',4,"A teacher says, 'So you are worried about the homework load, is that right?' This is:","checking understanding by paraphrasing",["ending the conversation","changing the topic","giving an order"],"Restating confirms meaning.")
H('314.d.2.C',3,"A website where a teacher posts updates that others can comment on is a:","blog",["podcast","vlog","wiki"],"Blogs are posts with comments.")
H('314.d.2.C',4,"A recorded audio program that students can listen to online is a:","podcast",["wiki","infographic","blog"],"Podcasts are audio episodes.")
H('314.d.2.D',3,"A professional email to a parent should include:","a clear subject line and polite greeting",["all capital letters","emojis only","no signature"],"Format signals professionalism.")
H('314.d.2.D',4,"Before sending an email about a student, a teacher should:","proofread and protect student privacy",["copy the whole class","use slang","add personal opinions"],"Accuracy and privacy matter.")
H('314.d.2.E',3,"Teachers collaborate effectively by:","sharing ideas and resources in team meetings",["working in isolation","hiding materials","criticizing publicly"],"Collaboration improves teaching.")
H('314.d.2.E',4,"A professional learning community (PLC) is a group of teachers who:","meet regularly to improve student learning",["compete for awards","avoid sharing","meet only socially"],"PLCs focus on learning.")
H('314.d.2.F',3,"Clear assignment directions should include:","what to do, how, and the due date",["only the title","nothing in writing","a hidden deadline"],"Students need complete directions.")
H('314.d.2.F',4,"Giving feedback on a student's work is most useful when it is:","specific and timely",["vague and late","only a grade","negative only"],"Specific feedback guides improvement.")
H('314.d.2.G',3,"To make group work fair, a teacher can assign:","roles such as recorder and reporter",["no roles","one worker","the same job to all"],"Roles share responsibility.")
H('314.d.2.G',4,"A strategy where students first think alone, then discuss with a partner, then share with the class is called:","think-pair-share",["jigsaw review","lecture-only","silent reading"],"Think-pair-share builds participation.")
H('314.d.2.H',3,"A teacher uses simple words and visuals for an English learner. This is:","adapting communication to student needs",["lowering expectations","ignoring the student","teaching less content"],"Supports make content accessible.")
H('314.d.2.H',4,"A student with a hearing impairment may need the teacher to:","face the student and use visual supports",["speak louder from behind","avoid the student","speed up speech"],"Visual access helps.")
H('314.d.3.A',3,"Digital literacy means being able to:","find, evaluate, and use information online",["avoid computers","type only","copy others' work"],"Digital literacy is critical use.")
H('314.d.3.A',4,"Before sharing an article online, a digitally literate person checks:","the source's credibility",["its font size","its page color","its ads"],"Credibility matters.")
H('314.d.3.B',3,"To narrow a web search, a teacher can add:","specific keywords",["random symbols","more ads","a longer URL"],"Specific words focus results.")
H('314.d.3.B',4,"Putting a phrase in quotation marks in a search tells the search engine to find:","that exact phrase",["unrelated pages","only images","only videos"],"Quotes request exact matches.")
H('314.d.3.C',3,"A database is best for:","searching organized collections of information",["playing games","posting jokes","sending greetings"],"Databases store searchable data.")
H('314.d.3.C',4,"Interactive games differ from digital videos because games:","require the learner to respond and make choices",["cannot be used for teaching","play without any input","only show text"],"Games are interactive.")
H('314.d.3.D',3,"When choosing educational software, a teacher should check that it:","matches learning objectives and is age-appropriate",["is the flashiest","has the most ads","is the newest only"],"Software should fit the learning goal.")
H('314.d.3.D',4,"A spreadsheet program is best for:","organizing data and calculating results",["editing video","writing music only","drawing logos only"],"Spreadsheets calculate and chart data.")
H('314.d.4.A',3,"FERPA protects:","the privacy of student education records",["school bus routes","teacher salaries","cafeteria menus"],"FERPA governs education records.")
H('314.d.4.A',4,"COPPA places limits on collecting personal information from children under age:","13",["8","16","18"],"COPPA protects children under 13.")
H('314.d.4.B',3,"Using a copyrighted image in class is usually allowed when:","it falls under fair use or has permission",["it is on the internet","it is popular","it is pretty"],"Fair use or permission is required.")
H('314.d.4.B',4,"Creative Commons licenses let creators:","share their work while setting conditions for its use",["hide their work","delete their work","prevent all sharing"],"CC licenses clarify permitted use.")
H('314.d.4.C',3,"In the SAMR model, 'substitution' means technology:","replaces a traditional tool with no functional change",["creates new tasks","redefines learning","changes the lesson entirely"],"Substitution is the lowest level.")
H('314.d.4.C',4,"In SAMR, the highest level, where technology allows tasks not possible before, is:","redefinition",["substitution","augmentation","modification"],"Redefinition transforms learning.")
H('314.d.4.D',3,"Before using a new app with students, a teacher should usually:","get it approved by the district",["use it secretly","ask students to sign up with personal emails","download it without checking"],"Approval protects privacy.")
H('314.d.4.D',4,"A district's acceptable use policy (AUP) explains:","how technology may and may not be used",["lunch prices","bus schedules","parking rules"],"AUPs set technology rules.")
H('314.d.4.E',3,"To keep students on task during device use, a teacher can:","set clear expectations and monitor screens",["leave the room","allow any site","ignore off-task use"],"Monitoring supports focus.")
H('314.d.4.E',4,"A routine where devices are closed during instruction helps:","keep students focused on the teacher",["increase distractions","remove rules","reduce learning"],"Clear routines limit distractions.")
H('314.d.5.A',3,"Interactive polls can increase engagement because students:","participate and get instant feedback",["sit passively","avoid thinking","skip the lesson"],"Polls make learning active.")
H('314.d.5.A',4,"Technology improves engagement most when it:","supports the learning goal",["entertains only","replaces teaching","is used constantly"],"Purpose drives effective use.")
H('314.d.5.B',3,"Which is a 21st-century learning skill?","Collaboration",["Rote copying","Silent compliance","Memorizing alone"],"Collaboration is a core modern skill.")
H('314.d.5.B',4,"The four Cs of 21st-century skills are critical thinking, creativity, communication, and:","collaboration",["competition","calculation","compliance"],"The fourth C is collaboration.")
H('314.d.5.C',3,"A teacher could use a presentation program to:","share visuals and organize key points",["replace students","grade without review","print attendance"],"Slides organize information.")
